using System;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using LighFight.Runtime;
public static class NativeSupportIntegrationBuilder {
 const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 public static string MeshHash(Mesh mesh){using(var stream=new MemoryStream()){using(var w=new BinaryWriter(stream,System.Text.Encoding.UTF8,true)){foreach(var v in mesh.vertices){w.Write(v.x);w.Write(v.y);w.Write(v.z);}foreach(var v in mesh.uv){w.Write(v.x);w.Write(v.y);}foreach(int t in mesh.triangles)w.Write(t);foreach(var m in mesh.bindposes)for(int n=0;n<16;n++)w.Write(m[n]);using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){foreach(var c in counts)w.Write(c);foreach(var b in weights){w.Write(b.boneIndex);w.Write(b.weight);}}}using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream.ToArray())).Replace("-","").ToLowerInvariant();}}
 public static void Export(){foreach(string who in new[]{"Rose","Island","Ranger","Bone"}){string folder="Assets/NativeSupport/"+who;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/candidate.prefab");var overlay=prefab.GetComponent<NativeSupportOverlay>();var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>();string path=folder+"/integration.asset";var cat=AssetDatabase.LoadAssetAtPath<NativeSupportCatalog>(path);if(!cat){cat=ScriptableObject.CreateInstance<NativeSupportCatalog>();AssetDatabase.CreateAsset(cat,path);}cat.character=who;cat.meshPreservationHash=MeshHash(skin.sharedMesh);cat.vertexCount=skin.sharedMesh.vertexCount;cat.triangleCount=skin.sharedMesh.triangles.Length/3;cat.entries=overlay.entries.Where(e=>!e.held).ToArray();cat.carriers=cat.entries.Select(e=>AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"/Clips/"+e.state+".carrier.anim")).ToArray();cat.footPoints=overlay.supportPoints;cat.bodyPoints=overlay.defeatBodyPoints;cat.hipBindAnchor=overlay.hipBindAnchor;cat.nativeMaxCorrection=overlay.nativeMaxCorrection;EditorUtility.SetDirty(cat);}AssetDatabase.SaveAssets();Debug.Log("AGENT_RESULT native integration catalogs exported");}
 public static void Package(){Export();string packet=Path.GetFullPath("../NativeSupportIntegrationPacket");Directory.CreateDirectory(packet);var catalogs=new[]{"Rose","Island","Ranger","Bone"}.Select(w=>"Assets/NativeSupport/"+w+"/integration.asset").ToArray();var assets=AssetDatabase.GetDependencies(catalogs,true).Concat(new[]{"Assets/NativeSupport/NativeSupportOverlay.cs","Assets/NativeSupport/NativeSupportPoseData.cs","Assets/NativeSupport/NativeSupportCatalog.cs","Assets/Editor/NativeSupportIntegrationBuilder.cs"}).Distinct().OrderBy(s=>s).ToArray();if(assets.Any(p=>p.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Unexpected original model build dependency in native curve catalog");File.WriteAllLines(Path.Combine(packet,"runtime-asset-manifest.txt"),assets);AssetDatabase.ExportPackage(assets,Path.Combine(packet,"native-support-runtime.unitypackage"),ExportPackageOptions.Default);Debug.Log("AGENT_RESULT native support runtime integration package exported "+assets.Length+" assets");}
 // Call after the main builder's ordinary Human controller, native fingers, and combat grounding are complete.
 // The passed AnimatorController must already be a per-character builder-owned instance.
 public static void Attach(GameObject generated,AnimatorController controller,NativeSupportCatalog catalog,bool includeNativeGuard=false){var selected=catalog.entries.Where(e=>includeNativeGuard||e.state!="Guard").ToArray();var animator=generated.GetComponentInChildren<Animator>();var skin=generated.GetComponentInChildren<SkinnedMeshRenderer>();var ground=generated.GetComponent<CandidateFootGrounding>();var view=generated.GetComponent<FighterView>();var fingers=generated.GetComponent<NativeFingerPoseDriver>();if(MeshHash(skin.sharedMesh)!=catalog.meshPreservationHash)throw new InvalidOperationException("Native support original vertex/UV/topology/bind/weight fingerprint mismatch: "+catalog.character);if(catalog.entries.Length!=catalog.carriers.Length)throw new InvalidOperationException("Native carrier count mismatch");var clips=((FighterView.NativeClip[])typeof(FighterView).GetField("nativeClips",Private).GetValue(view)).ToList();var sm=controller.layers[0].stateMachine;for(int i=0;i<catalog.entries.Length;i++){var e=catalog.entries[i];if(!selected.Contains(e))continue;if(!e.pose||!catalog.carriers[i])throw new InvalidOperationException("Original pose or phase carrier missing");foreach(var path in e.pose.JointPaths)if(path.Length>0&&!animator.transform.Find(path))throw new InvalidOperationException("Original native path missing "+path);var state=sm.states.FirstOrDefault(s=>s.state.name==e.state).state;if(!state)state=sm.AddState(e.state);state.motion=catalog.carriers[i];state.iKOnFeet=false;clips.RemoveAll(c=>c.state==e.state);clips.Add(new FighterView.NativeClip{state=e.state,clip=catalog.carriers[i]});}animator.runtimeAnimatorController=controller;view.UseNativeMotion(clips.ToArray());var overlay=generated.GetComponent<NativeSupportOverlay>();if(!overlay)overlay=generated.AddComponent<NativeSupportOverlay>();overlay.animator=animator;overlay.grounding=ground;overlay.entries=selected.Select(e=>new NativeSupportOverlay.Entry{state=e.state,sourceName=e.sourceName,pose=e.pose,loop=e.loop,held=e.held,heldPhase=e.heldPhase}).ToArray();overlay.hipBindAnchor=catalog.hipBindAnchor;overlay.hasHipBindAnchor=true;overlay.supportPoints=(ground.shoePoints??new CandidateFootGrounding.Point[0]).Concat(catalog.footPoints).GroupBy(p=>JsonUtility.ToJson(p)).Select(g=>g.First()).ToArray();overlay.defeatBodyPoints=catalog.bodyPoints;overlay.nativeMaxCorrection=catalog.nativeMaxCorrection;overlay.baseMaxCorrection=ground.maxCorrection;overlay.enabled=true;var closed=(string[])typeof(NativeFingerPoseDriver).GetField("closedStates",Private).GetValue(fingers);typeof(NativeFingerPoseDriver).GetField("closedStates",Private).SetValue(fingers,closed.Where(s=>!selected.Any(e=>e.state==s)).ToArray());fingers.enabled=true;ground.enabled=true;}
}
